/**
 * Billing-period arithmetic: where a period ends, how many months it spans and
 * what a change in the middle of one costs.
 *
 * Everything is UTC and pure — the callers hand in the instant, nothing here
 * reads the clock. A period runs from its start up to (not including) its end,
 * and the next period starts exactly where the previous one ended.
 */
import type { BillingInterval } from "@/types/billing";

const DAY_MS = 24 * 60 * 60 * 1000;

/** Calendar months one period of this interval spans. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  if (month === 1) return isLeapYear(year) ? 29 : 28;
  return [3, 5, 8, 10].includes(month) ? 30 : 31;
}

/**
 * `start` moved on by whole calendar months, keeping the time of day. The day
 * of the month is kept too, or clamped to the last day of the target month
 * when it has no such day (31 Jan + 1 month → 28 Feb).
 */
export function addCalendarMonths(start: Date, months: number): Date {
  const absoluteMonth =
    start.getUTCFullYear() * 12 + start.getUTCMonth() + months;
  const year = Math.floor(absoluteMonth / 12);
  const month = absoluteMonth - year * 12;

  const end = new Date(start.getTime());
  end.setUTCFullYear(year, month, Math.min(start.getUTCDate(), daysInMonth(year, month)));
  return end;
}

/** The instant the period that starts at `start` ends. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addCalendarMonths(start, monthsInInterval(interval));
}

/** Whole days between the start and the end of a period — rounded, at least one. */
export function daysInPeriod(periodStart: Date, periodEnd: Date): number {
  return Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / DAY_MS),
  );
}

/**
 * Days from `now` to the period end, counting a started day as a whole one
 * (14 days 22 hours left is 15). None once the end has been reached.
 */
export function daysLeftInPeriod(now: Date, periodEnd: Date): number {
  const left = periodEnd.getTime() - now.getTime();
  return left <= 0 ? 0 : Math.ceil(left / DAY_MS);
}

/**
 * The share of `fullCents` that falls on the rest of the period, rounded down
 * to whole cents. A change that somehow precedes the period is charged the
 * full period, never more.
 */
export function prorateCents(
  fullCents: number,
  now: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  const total = daysInPeriod(periodStart, periodEnd);
  const left = Math.min(daysLeftInPeriod(now, periodEnd), total);
  return Math.floor((fullCents * left) / total);
}

