export function daysLeftInPeriod(now: Date, periodEnd: Date): number {
  const left = periodEnd.getTime() - now.getTime();
  return left <= 0 ? 0 : Math.ceil(left / DAY_MS);
}

/**
 * The share of `fullCents` that falls on the rest of the period, rounded down
 * to whole cents. A change that somehow precedes the period is charged the
 * full period, never more.
 */
export function prorateCents(
  fullCents: number,
  now: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  const total = daysInPeriod(periodStart, periodEnd);
  const left = Math.min(daysLeftInPeriod(now, periodEnd), total);
  return Math.floor((fullCents * left) / total);
}

