cat > src/server/jobs/billing-renewal-job.ts <<'EOF'
/**
 * Renews subscriptions whose period ended, invoices every renewed paid period
 * and carries out cancellations whose date has arrived.
 *
 * Must call (do not reimplement): emit, periodEndFor, periodChargeCents, announceInvoice
 */
import { periodEndFor } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as billingRepo from "@/server/repositories/billing-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import {
  announceInvoice,
  periodChargeCents,
} from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

/** Subscriptions read per page; the sweep covers every workspace, page by page. */
const PAGE_SIZE = 200;

/** Where a cancelled workspace lands, on a monthly period. */
const CANCELED_TO = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * One sweep over every live workspace's subscription at the instant `now`.
 * `active` subscriptions whose period ended are renewed period by period,
 * `canceled` ones whose date arrived move to the free plan; everything else —
 * trials, past-due, a cancellation still ahead — is left alone.
 *
 * Replay-safe: each period (and its invoice) is committed in one step that
 * only applies to the row as it was read, so running again at the same instant
 * — or two runs overlapping — finds nothing left to do and announces nothing.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);
    let afterId: string | null = null;

    for (;;) {
      const page = await subscriptionRepo.listSubscriptionsForBilling(
        afterId,
        PAGE_SIZE,
      );
      const last = page[page.length - 1];
      if (last === undefined) break;

      for (const subscription of page) {
        try {
          if (await settle(subscription, now, stamp)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      if (page.length < PAGE_SIZE) break;
      afterId = last.id;
    }
  });
}

/** True when the subscription was changed. */
async function settle(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  if (subscription.status === "canceled") {
    if (subscription.cancelAt === null) return false;
    if (parseIso(subscription.cancelAt).getTime() > now.getTime()) return false;
    return endCancellation(subscription, now, stamp);
  }

  if (subscription.status === "active") {
    return renew(subscription, now, stamp);
  }

  return false;
}

/**
 * Moves the period on once per elapsed interval until its end lies after
 * `now`. A paid period is invoiced for the full charge at the seat count of
 * that moment; the free plan moves on without invoices.
 */
async function renew(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  let current = subscription;
  let renewed = false;

  while (parseIso(current.currentPeriodEnd).getTime() <= now.getTime()) {
    const periodStart = parseIso(current.currentPeriodEnd);
    const periodEnd = periodEndFor(periodStart, current.interval);

    const committed = await billingRepo.commitSubscriptionChange(
      current,
      {
        currentPeriodStart: toIsoTimestamp(periodStart),
        currentPeriodEnd: toIsoTimestamp(periodEnd),
      },
      current.plan === "free"
        ? null
        : {
            amountCents: periodChargeCents(
              current.plan,
              current.seats,
              current.interval,
            ),
            currency: "usd",
            periodStart: toIsoTimestamp(periodStart),
            periodEnd: toIsoTimestamp(periodEnd),
          },
    );
    // Somebody else got to this row first; whatever they did stands.
    if (committed === null) break;

    renewed = true;
    current = committed.subscription;
    if (committed.invoice) await announceInvoice(committed.invoice, stamp);
  }

  return renewed;
}

/**
 * The cancellation date has arrived: the workspace is on the free plan as of
 * that date, with a fresh monthly period starting there. If that period has
 * itself run out by now, it is rolled forward in the same pass, so a replay
 * has nothing left to do.
 */
async function endCancellation(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;

  const periodStart = parseIso(subscription.cancelAt);
  const committed = await billingRepo.commitSubscriptionChange(
    subscription,
    {
      plan: CANCELED_TO,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: toIsoTimestamp(periodStart),
      currentPeriodEnd: toIsoTimestamp(periodEndFor(periodStart, "monthly")),
    },
    null,
  );
  if (committed === null) return false;

  if (subscription.plan !== CANCELED_TO) {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: stamp,
      from: subscription.plan,
      to: CANCELED_TO,
    });
  }

  await renew(committed.subscription, now, stamp);
  return true;
}
