          if (await settle(subscription, now, stamp)) result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("billing renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      if (page.length < PAGE_SIZE) break;
      afterId = last.id;
    }
  });
}

/** True when the subscription was changed. */
async function settle(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  if (subscription.status === "canceled") {
    if (subscription.cancelAt === null) return false;
    if (parseIso(subscription.cancelAt).getTime() > now.getTime()) return false;
    return endCancellation(subscription, now, stamp);
  }

  if (subscription.status === "active") {
    return renew(subscription, now, stamp);
  }

  return false;
}

/**
 * Moves the period on once per elapsed interval until its end lies after
 * `now`. A paid period is invoiced for the full charge at the seat count of
 * that moment; the free plan moves on without invoices.
 */
async function renew(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  let current = subscription;
  let renewed = false;

  while (parseIso(current.currentPeriodEnd).getTime() <= now.getTime()) {
    const periodStart = parseIso(current.currentPeriodEnd);
    const periodEnd = periodEndFor(periodStart, current.interval);

    const committed = await billingRepo.commitSubscriptionChange(
      current,
      {
        currentPeriodStart: toIsoTimestamp(periodStart),
        currentPeriodEnd: toIsoTimestamp(periodEnd),
      },
      current.plan === "free"
        ? null
        : {
            amountCents: periodChargeCents(
              current.plan,
              current.seats,
              current.interval,
            ),
            currency: "usd",
            periodStart: toIsoTimestamp(periodStart),
            periodEnd: toIsoTimestamp(periodEnd),
          },
    );
    // Somebody else got to this row first; whatever they did stands.
    if (committed === null) break;

    renewed = true;
    current = committed.subscription;
    if (committed.invoice) await announceInvoice(committed.invoice, stamp);
  }

  return renewed;
}

/**
 * The cancellation date has arrived: the workspace is on the free plan as of
 * that date, with a fresh monthly period starting there. If that period has
 * itself run out by now, it is rolled forward in the same pass, so a replay
 * has nothing left to do.
 */
async function endCancellation(
  subscription: Subscription,
  now: Date,
  stamp: ReturnType<typeof toIsoTimestamp>,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;

  const periodStart = parseIso(subscription.cancelAt);
  const committed = await billingRepo.commitSubscriptionChange(
    subscription,
    {
      plan: CANCELED_TO,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: toIsoTimestamp(periodStart),
      currentPeriodEnd: toIsoTimestamp(periodEndFor(periodStart, "monthly")),
    },
    null,
  );
  if (committed === null) return false;

  if (subscription.plan !== CANCELED_TO) {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: stamp,
      from: subscription.plan,
      to: CANCELED_TO,
    });
  }

  await renew(committed.subscription, now, stamp);
  return true;
}
EOF
