/** Period ends, month clamping and proration arithmetic. */
import { describe, expect, it } from "vitest";
import {
  addCalendarMonths,
  daysInPeriod,
  daysLeftInPeriod,
  monthsInInterval,
  periodEndFor,
  prorateCents,
} from "@/lib/billing-period";

const at = (value: string): Date => new Date(value);

describe("lib/billing-period", () => {
  it("spans one month for monthly and twelve for annual", () => {
    expect(monthsInInterval("monthly")).toBe(1);
    expect(monthsInInterval("annual")).toBe(12);
  });

  it("ends a monthly period on the same day and time of the next month", () => {
    expect(periodEndFor(at("2026-03-15T10:30:45.123Z"), "monthly").toISOString()).toBe(
      "2026-04-15T10:30:45.123Z",
    );
    expect(periodEndFor(at("2026-12-31T23:59:59.999Z"), "monthly").toISOString()).toBe(
      "2027-01-31T23:59:59.999Z",
    );
  });

  it("clamps to the last day of a shorter month", () => {
    expect(periodEndFor(at("2026-01-31T08:00:00.000Z"), "monthly").toISOString()).toBe(
      "2026-02-28T08:00:00.000Z",
    );
    expect(periodEndFor(at("2028-01-31T08:00:00.000Z"), "monthly").toISOString()).toBe(
      "2028-02-29T08:00:00.000Z",
    );
    expect(periodEndFor(at("2026-03-31T08:00:00.000Z"), "monthly").toISOString()).toBe(
      "2026-04-30T08:00:00.000Z",
    );
  });

  it("carries a clamped day forward instead of snapping back", () => {
    const first = periodEndFor(at("2026-01-31T08:00:00.000Z"), "monthly");
    const second = periodEndFor(first, "monthly");
    expect(second.toISOString()).toBe("2026-03-28T08:00:00.000Z");
  });

  it("ends an annual period on the same day and month of the next year", () => {
    expect(periodEndFor(at("2026-06-10T00:00:00.000Z"), "annual").toISOString()).toBe(
      "2027-06-10T00:00:00.000Z",
    );
    expect(periodEndFor(at("2028-02-29T12:00:00.000Z"), "annual").toISOString()).toBe(
      "2029-02-28T12:00:00.000Z",
    );
  });

  it("moves across year boundaries and by arbitrary month counts", () => {
    expect(addCalendarMonths(at("2026-11-30T00:00:00.000Z"), 3).toISOString()).toBe(
      "2027-02-28T00:00:00.000Z",
    );
    expect(addCalendarMonths(at("2026-05-31T00:00:00.000Z"), 12).toISOString()).toBe(
      "2027-05-31T00:00:00.000Z",
    );
  });

  it("counts the days of a period as whole days, at least one", () => {
    expect(daysInPeriod(at("2026-03-01T00:00:00Z"), at("2026-04-01T00:00:00Z"))).toBe(31);
    expect(daysInPeriod(at("2026-02-01T00:00:00Z"), at("2026-03-01T00:00:00Z"))).toBe(28);
    expect(daysInPeriod(at("2026-03-01T00:00:00Z"), at("2026-03-01T01:00:00Z"))).toBe(1);
  });

  it("counts a started day as a whole day left, and none at the end", () => {
    const end = at("2026-04-01T00:00:00Z");
    expect(daysLeftInPeriod(at("2026-03-17T02:00:00Z"), end)).toBe(15);
    expect(daysLeftInPeriod(at("2026-03-17T00:00:00Z"), end)).toBe(15);
    expect(daysLeftInPeriod(at("2026-03-31T23:59:59Z"), end)).toBe(1);
    expect(daysLeftInPeriod(end, end)).toBe(0);
    expect(daysLeftInPeriod(at("2026-04-02T00:00:00Z"), end)).toBe(0);
  });

  it("scales the full charge by days left and rounds down to whole cents", () => {
    const start = at("2026-03-01T00:00:00Z");
    const end = at("2026-04-01T00:00:00Z");

    // 15 of 31 days left: 1000 * 15 / 31 = 483.87…
    expect(prorateCents(1_000, at("2026-03-17T02:00:00Z"), start, end)).toBe(483);
    // The whole period left is the whole charge.
    expect(prorateCents(1_000, start, start, end)).toBe(1_000);
    // Nothing left, nothing charged.
    expect(prorateCents(1_000, end, start, end)).toBe(0);
    // Never more than the full period.
    expect(prorateCents(1_000, at("2026-02-01T00:00:00Z"), start, end)).toBe(1_000);
  });
});
EOF
