describe("jobs/billing-renewal-job", () => {
  it("renews an ended monthly period and invoices it in full", async () => {
    const tenant = await tenantOn("renew-monthly", "starter", {
      seats: 3,
      currentPeriodStart: "2026-02-15T09:00:00.000Z",
      currentPeriodEnd: "2026-03-15T09:00:00.000Z",
    });

    const result = await runBillingRenewalJob(new Date("2026-03-15T09:00:00.000Z"));

    expect(result.kind).toBe("billing-renewal");
    expect(result.failed).toBe(0);

    const after = await current(tenant.org.id);
    expect(after.currentPeriodStart).toBe("2026-03-15T09:00:00.000Z");
    expect(after.currentPeriodEnd).toBe("2026-04-15T09:00:00.000Z");

    const invoices = await listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 900 * 3,
      currency: "usd",
      periodStart: "2026-03-15T09:00:00.000Z",
      periodEnd: "2026-04-15T09:00:00.000Z",
      paidAt: null,
    });
  });

  it("leaves a period alone until its end has arrived", async () => {
    const tenant = await tenantOn("not-yet", "starter", {
      currentPeriodStart: "2026-02-15T09:00:00.000Z",
      currentPeriodEnd: "2026-03-15T09:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-15T08:59:59.999Z"));

    expect((await current(tenant.org.id)).currentPeriodEnd).toBe("2026-03-15T09:00:00.000Z");
    expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
  });

  it("catches up one period per elapsed interval, each invoiced", async () => {
    const tenant = await tenantOn("catch-up", "growth", {
      seats: 2,
      currentPeriodStart: "2026-01-31T08:00:00.000Z",
      currentPeriodEnd: "2026-02-28T08:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-04-30T12:00:00.000Z"));

    const invoices = await listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoices.map((invoice) => [invoice.periodStart, invoice.periodEnd])).toEqual([
      ["2026-04-28T08:00:00.000Z", "2026-05-28T08:00:00.000Z"],
      ["2026-03-28T08:00:00.000Z", "2026-04-28T08:00:00.000Z"],
      ["2026-02-28T08:00:00.000Z", "2026-03-28T08:00:00.000Z"],
    ]);
    expect(invoices.every((invoice) => invoice.amountCents === 1_900 * 2)).toBe(true);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);

    const after = await current(tenant.org.id);
    expect(after.currentPeriodStart).toBe("2026-04-28T08:00:00.000Z");
    expect(after.currentPeriodEnd).toBe("2026-05-28T08:00:00.000Z");
  });

  it("invoices an annual period for twelve months", async () => {
    const tenant = await tenantOn("annual", "growth", {
      interval: "annual",
      seats: 4,
      currentPeriodStart: "2027-02-28T00:00:00.000Z",
      currentPeriodEnd: "2028-02-29T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2028-03-01T00:00:00.000Z"));

    const [invoice] = await listInvoices(tenant.actors.owner, tenant.org.id);
    expect(invoice?.amountCents).toBe(1_900 * 4 * 12);
    expect(invoice?.periodEnd).toBe("2029-02-28T00:00:00.000Z");
  });

  it("moves the free plan on without an invoice", async () => {
    const tenant = await tenantOn("free-renew", "free", {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));

    const after = await current(tenant.org.id);
    expect(after.currentPeriodStart).toBe("2026-03-01T00:00:00.000Z");
    expect(after.currentPeriodEnd).toBe("2026-04-01T00:00:00.000Z");
    expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
  });

  it("leaves trialing and past-due subscriptions to other jobs", async () => {
    const trial = await tenantOn("trial", "starter", {
      status: "trialing",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });
    const overdue = await tenantOn("past-due", "starter", {
      status: "past_due",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));

    for (const tenant of [trial, overdue]) {
      expect((await current(tenant.org.id)).currentPeriodEnd).toBe("2026-03-01T00:00:00.000Z");
      expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    }
  });

  it("skips archived workspaces entirely", async () => {
    const tenant = await tenantOn("archived", "starter", {
      currentPeriodStart: "2026-02-01T00:00:00.000Z",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });
    await orgRepo.archiveOrg(tenant.org.id);

    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));

    expect((await current(tenant.org.id)).currentPeriodEnd).toBe("2026-03-01T00:00:00.000Z");
    expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
  });

  it("covers every workspace, however many there are", async () => {
    const owner = await createTenant("many-owner", "free");
    const orgIds: OrgId[] = [];

    for (let index = 0; index < 450; index += 1) {
      const org = await orgRepo.insertOrg(
        { name: `Bulk ${index}`, slug: `bulk-${index}`, plan: "starter" },
        owner.userIds.owner,
      );
      await subscriptionRepo.insertSubscription(org.id, "starter", "monthly");
      seedSubscription(org.id, {
        status: "active",
        currentPeriodStart: "2026-02-01T00:00:00.000Z",
        currentPeriodEnd: "2026-03-01T00:00:00.000Z",
      });
      orgIds.push(org.id);
    }

    const result = await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));
    expect(result.processed).toBeGreaterThanOrEqual(450);

    for (const orgId of orgIds) {
      expect((await current(orgId)).currentPeriodEnd).toBe("2026-04-01T00:00:00.000Z");
    }
  });

  it("is a no-op the second time at the same instant", async () => {
    const tenant = await tenantOn("replay", "starter", {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    const now = new Date("2026-03-10T00:00:00.000Z");
    const issued = collect("billing.invoice_issued");

    await runBillingRenewalJob(now);
    const afterFirst = await current(tenant.org.id);
    const invoicesFirst = await listInvoices(tenant.actors.owner, tenant.org.id);

    const second = await runBillingRenewalJob(now);

    expect(second.processed).toBe(0);
    expect(await current(tenant.org.id)).toEqual(afterFirst);
    expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toEqual(invoicesFirst);
    expect(issued.filter((event) => event.orgId === tenant.org.id)).toHaveLength(2);
  });

  it("does not double-bill when two runs overlap", async () => {
    const tenant = await tenantOn("overlap", "starter", {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    const now = new Date("2026-02-20T00:00:00.000Z");

    await Promise.all([runBillingRenewalJob(now), runBillingRenewalJob(now)]);

    expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(1);
    expect((await current(tenant.org.id)).currentPeriodEnd).toBe("2026-03-01T00:00:00.000Z");
  });

  it("publishes, audits and announces each invoice once, to the owner only", async () => {
    const tenant = await tenantOn("announce", "starter", {
      seats: 2,
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    const issued = collect("billing.invoice_issued");

    await runBillingRenewalJob(new Date("2026-02-01T00:00:00.000Z"));
    await runBillingRenewalJob(new Date("2026-02-01T00:00:00.000Z"));

    const [invoice] = await listInvoices(tenant.actors.owner, tenant.org.id);
    expect(issued).toHaveLength(1);
    expect(issued[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: null,
      invoiceId: invoice?.id,
      invoiceNumber: invoice?.number,
      amountCents: 1_800,
      periodStart: "2026-02-01T00:00:00.000Z",
      periodEnd: "2026-03-01T00:00:00.000Z",
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "subscription",
      subjectId: tenant.org.id,
    });

    for (const [role, expected] of [
      ["owner", 1],
      ["admin", 0],
      ["member", 0],
      ["viewer", 0],
    ] as const) {
      const page = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds[role],
        unreadOnly: false,
        kind: ["invoice_issued"],
        limit: 25,
        cursor: null,
      });
      expect(page.items, role).toHaveLength(expected);
    }
  });

  describe("cancellations", () => {
    it("does nothing before the cancellation date, whatever the period end says", async () => {
      const tenant = await tenantOn("cancel-later", "growth", {
        status: "canceled",
        cancelAt: "2026-04-01T00:00:00.000Z",
        currentPeriodStart: "2026-01-01T00:00:00.000Z",
        currentPeriodEnd: "2026-02-01T00:00:00.000Z",
      });
      const changed = collect("billing.plan_changed");

      await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

      const after = await current(tenant.org.id);
      expect(after).toMatchObject({
        plan: "growth",
        status: "canceled",
        cancelAt: "2026-04-01T00:00:00.000Z",
        currentPeriodEnd: "2026-02-01T00:00:00.000Z",
      });
      expect(changed).toHaveLength(0);
      expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });

    it("moves to the free plan as of the cancellation date, once", async () => {
      const tenant = await tenantOn("cancel-now", "growth", {
        status: "canceled",
        cancelAt: "2026-03-10T12:00:00.000Z",
        currentPeriodStart: "2026-02-10T12:00:00.000Z",
        currentPeriodEnd: "2026-03-10T12:00:00.000Z",
      });
      const changed = collect("billing.plan_changed");
      const issued = collect("billing.invoice_issued");
      const now = new Date("2026-03-10T12:00:00.000Z");

      await runBillingRenewalJob(now);
      await runBillingRenewalJob(now);

      expect(await current(tenant.org.id)).toMatchObject({
        plan: "free",
        interval: "monthly",
        status: "active",
        cancelAt: null,
        currentPeriodStart: "2026-03-10T12:00:00.000Z",
        currentPeriodEnd: "2026-04-10T12:00:00.000Z",
      });
      expect(changed).toHaveLength(1);
      expect(changed[0]).toMatchObject({
        orgId: tenant.org.id,
        actorId: null,
        from: "growth",
        to: "free",
      });
      expect(issued).toHaveLength(0);
      expect(await listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });

    it("rolls the free plan forward when its first period has also run out", async () => {
      const tenant = await tenantOn("cancel-stale", "starter", {
        status: "canceled",
        cancelAt: "2026-01-15T00:00:00.000Z",
        currentPeriodStart: "2025-12-15T00:00:00.000Z",
        currentPeriodEnd: "2026-01-15T00:00:00.000Z",
      });
      const now = new Date("2026-03-20T00:00:00.000Z");

      await runBillingRenewalJob(now);
      const afterFirst = await current(tenant.org.id);
      await runBillingRenewalJob(now);

      expect(afterFirst).toMatchObject({
        plan: "free",
        status: "active",
        currentPeriodStart: "2026-03-15T00:00:00.000Z",
        currentPeriodEnd: "2026-04-15T00:00:00.000Z",
      });
      expect(await current(tenant.org.id)).toEqual(afterFirst);
    });
  });

  it("stamps the job result with its kind and start", async () => {
    const result = await runBillingRenewalJob(new Date("2026-03-10T00:00:00.000Z"));
    expect(result.kind).toBe("billing-renewal");
    expect(toIsoTimestamp(new Date(result.startedAt))).toBe(result.startedAt);
    expect(organizations).toBeDefined();
  });
});
