import type { PlanId, Subscription } from "@/types/billing";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const PERIOD_START = "2026-03-01T00:00:00.000Z";
const PERIOD_END = "2026-04-01T00:00:00.000Z";

async function tenantOn(
  slug: string,
  plan: PlanId,
  seed: Partial<Pick<Subscription, "status" | "seats" | "interval" | "currentPeriodStart" | "currentPeriodEnd">> = {},
): Promise<Tenant> {
  const tenant = await createTenant(slug, plan);
  getDb()
    .update(subscriptions)
    .set({
      status: "active",
      seats: 4,
      currentPeriodStart: PERIOD_START,
      currentPeriodEnd: PERIOD_END,
      ...seed,
    })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
  return tenant;
}

function collect<K extends keyof TaskflowEventMap>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

function at(moment: string): void {
  vi.useFakeTimers();
  vi.setSystemTime(new Date(moment));
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("services/billing-service proration", () => {
