/**
 * Mid-period seat and plan changes are charged for the rest of the period.
 *
 * Owner C implements `@/server/services/billing-service`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, subscriptions } from "@/server/db";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { PlanId, Subscription } from "@/types/billing";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const PERIOD_START = "2026-03-01T00:00:00.000Z";
const PERIOD_END = "2026-04-01T00:00:00.000Z";

async function tenantOn(
  slug: string,
  plan: PlanId,
  seed: Partial<Pick<Subscription, "status" | "seats" | "interval" | "currentPeriodStart" | "currentPeriodEnd">> = {},
): Promise<Tenant> {
  const tenant = await createTenant(slug, plan);
  getDb()
    .update(subscriptions)
    .set({
      status: "active",
      seats: 4,
      currentPeriodStart: PERIOD_START,
      currentPeriodEnd: PERIOD_END,
      ...seed,
    })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
  return tenant;
}

function collect<K extends keyof TaskflowEventMap>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

function at(moment: string): void {
  vi.useFakeTimers();
  vi.setSystemTime(new Date(moment));
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("services/billing-service proration", () => {
  describe("updateSeats", () => {
    it("charges added seats for the days left, rounded down", async () => {
      const tenant = await tenantOn("seats-add", "growth");
      const issued = collect("billing.invoice_issued");
      at("2026-03-17T02:00:00.000Z"); // 14 days 22 hours left → 15 of 31

      const updated = await billingService.updateSeats(tenant.actors.owner, {
        orgId: tenant.org.id,
        seats: 6,
      });

      expect(updated.seats).toBe(6);
      expect(updated.currentPeriodStart).toBe(PERIOD_START);
      expect(updated.currentPeriodEnd).toBe(PERIOD_END);

      // 1_900 × 2 seats × 1 month = 3_800; × 15 / 31 = 1_838.7…
      const invoices = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
      expect(invoices).toHaveLength(1);
      expect(invoices[0]).toMatchObject({
        amountCents: 1_838,
        currency: "usd",
        periodStart: PERIOD_START,
        periodEnd: PERIOD_END,
        paidAt: null,
      });
      expect(issued).toHaveLength(1);
      expect(issued[0]).toMatchObject({
        orgId: tenant.org.id,
        invoiceId: invoices[0]?.id,
        invoiceNumber: invoices[0]?.number,
        amountCents: 1_838,
      });
    });

    it("scales an annual period by twelve months", async () => {
      const tenant = await tenantOn("seats-annual", "starter", {
        interval: "annual",
        seats: 1,
        currentPeriodStart: "2026-01-01T00:00:00.000Z",
        currentPeriodEnd: "2027-01-01T00:00:00.000Z",
      });
      at("2026-01-01T00:00:00.000Z");

      await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 3 });

      const [invoice] = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
      expect(invoice?.amountCents).toBe(900 * 2 * 12);
    });

    it("charges nothing for removing seats", async () => {
      const tenant = await tenantOn("seats-remove", "growth");
      at("2026-03-10T00:00:00.000Z");

      const updated = await billingService.updateSeats(tenant.actors.owner, {
        orgId: tenant.org.id,
        seats: 2,
      });

      expect(updated.seats).toBe(2);
      expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });

    it("charges nothing once the period end has been reached", async () => {
      const tenant = await tenantOn("seats-late", "growth");
      at(PERIOD_END);

      await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 9 });

      expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });

    it("charges nothing when the share rounds down to zero cents", async () => {
      const tenant = await tenantOn("seats-zero", "starter", {
        seats: 1,
        currentPeriodStart: "2026-03-01T00:00:00.000Z",
        currentPeriodEnd: "2026-03-01T00:00:01.000Z",
      });
      at("2026-03-01T00:00:00.000Z");
      // One day in the period and one day left: the whole 900 cents.
      await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 2 });
      expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(1);

      const spare = await tenantOn("seats-zero-b", "starter", { seats: 1 });
      at("2026-03-31T23:00:00.000Z"); // 1 of 31 days left: 900 × 1 / 31 = 29
      await billingService.updateSeats(spare.actors.owner, { orgId: spare.org.id, seats: 2 });
      const [invoice] = await billingService.listInvoices(spare.actors.owner, spare.org.id);
      expect(invoice?.amountCents).toBe(29);
    });

    it("charges nothing on the free plan or during a trial", async () => {
      const free = await tenantOn("seats-free", "free", { seats: 1 });
      const trial = await tenantOn("seats-trial", "starter", { status: "trialing", seats: 1 });
      at("2026-03-02T00:00:00.000Z");

      await billingService.updateSeats(free.actors.owner, { orgId: free.org.id, seats: 3 });
      await billingService.updateSeats(trial.actors.owner, { orgId: trial.org.id, seats: 5 });

      expect(await billingService.listInvoices(free.actors.owner, free.org.id)).toHaveLength(0);
      expect(await billingService.listInvoices(trial.actors.owner, trial.org.id)).toHaveLength(0);
      expect((await subscriptionRepo.findSubscription(trial.org.id))?.seats).toBe(5);
    });

    it("still refuses seats above the plan's ceiling", async () => {
      const tenant = await tenantOn("seats-ceiling", "starter", { seats: 2 });

      await expect(
        billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 11 }),
      ).rejects.toThrow(/tops out at 10 seats/);
      expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });
  });

  describe("changePlan", () => {
    it("charges an upgrade's price difference for the rest of the period", async () => {
      const tenant = await tenantOn("plan-upgrade", "starter", { seats: 5 });
      const issued = collect("billing.invoice_issued");
      at("2026-03-17T02:00:00.000Z");

      const updated = await billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "growth",
        interval: "monthly",
      });

      expect(updated.plan).toBe("growth");
      expect(updated.currentPeriodStart).toBe(PERIOD_START);
      expect(updated.currentPeriodEnd).toBe(PERIOD_END);

      // (1_900 − 900) × 5 seats = 5_000; × 15 / 31 = 2_419.3…
      const [invoice] = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
      expect(invoice).toMatchObject({
        amountCents: 2_419,
        periodStart: PERIOD_START,
        periodEnd: PERIOD_END,
      });
      expect(issued).toHaveLength(1);
    });

    it("charges nothing for a downgrade or an unchanged plan", async () => {
      const down = await tenantOn("plan-down", "growth", { seats: 1 });
      const same = await tenantOn("plan-same", "growth", { seats: 1 });
      at("2026-03-05T00:00:00.000Z");

      await billingService.changePlan(down.actors.owner, {
        orgId: down.org.id,
        plan: "starter",
        interval: "monthly",
      });
      await billingService.changePlan(same.actors.owner, {
        orgId: same.org.id,
        plan: "growth",
        interval: "monthly",
      });

      expect(await billingService.listInvoices(down.actors.owner, down.org.id)).toHaveLength(0);
      expect(await billingService.listInvoices(same.actors.owner, same.org.id)).toHaveLength(0);
      expect((await subscriptionRepo.findSubscription(down.org.id))?.currentPeriodEnd).toBe(PERIOD_END);
    });

    it("keeps the trial period and charges nothing during a trial", async () => {
      const tenant = await tenantOn("plan-trial", "starter", { status: "trialing" });
      at("2026-03-05T00:00:00.000Z");

      const updated = await billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "annual",
      });

      expect(updated).toMatchObject({
        plan: "enterprise",
        interval: "annual",
        status: "active",
        currentPeriodStart: PERIOD_START,
        currentPeriodEnd: PERIOD_END,
      });
      expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });

    it("starts a fresh, fully invoiced period when leaving the free plan", async () => {
      const tenant = await tenantOn("plan-leave-free", "free", { seats: 3 });
      const issued = collect("billing.invoice_issued");
      at("2026-03-17T02:00:00.000Z");

      const updated = await billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "starter",
        interval: "annual",
      });

      expect(updated).toMatchObject({
        plan: "starter",
        interval: "annual",
        status: "active",
        currentPeriodStart: "2026-03-17T02:00:00.000Z",
        currentPeriodEnd: "2027-03-17T02:00:00.000Z",
      });

      const [invoice] = await billingService.listInvoices(tenant.actors.owner, tenant.org.id);
      expect(invoice).toMatchObject({
        amountCents: 900 * 3 * 12,
        periodStart: "2026-03-17T02:00:00.000Z",
        periodEnd: "2027-03-17T02:00:00.000Z",
      });
      expect(issued).toHaveLength(1);
    });

    it("charges nothing when moving to the free plan", async () => {
      const tenant = await tenantOn("plan-to-free", "starter", { seats: 2 });
      at("2026-03-05T00:00:00.000Z");

      await billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "free",
        interval: "monthly",
      });

      expect(await billingService.listInvoices(tenant.actors.owner, tenant.org.id)).toHaveLength(0);
    });

    it("lists invoices of the same period newest first", async () => {
