/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const currentPlan = await planFor(input.orgId);

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const before = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const now = new Date();

  // A plan change ends the trial: the org has made a deliberate choice, and
  // the trial period stays as it is — the first invoice comes when it ends.
  let patch: SubscriptionPatch = {
    plan: input.plan,
    interval: input.interval,
    status: "active",
  };
  let draft: InvoiceDraft | null = null;

  if (before.status === "active") {
    if (before.plan === "free" && input.plan !== "free") {
      // Leaving the free plan: a fresh period from this moment, billed in full.
      const periodStart = toIsoTimestamp(now);
      const periodEnd = toIsoTimestamp(periodEndFor(now, input.interval));
      patch = {
        ...patch,
        currentPeriodStart: periodStart,
        currentPeriodEnd: periodEnd,
      };
      draft = {
        amountCents: periodChargeCents(
          input.plan,
          before.seats,
          input.interval,
        ),
        currency: "usd",
        periodStart,
        periodEnd,
      };
    } else if (before.plan !== "free" && input.plan !== "free") {
      // Between two paid plans: only an upgrade is charged, for the price
      // difference over what is left of the unchanged period.
      const difference =
        getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(before.plan).priceCentsPerSeatMonthly;
      if (difference > 0) {
        draft = proratedDraft(
          before,
          difference * before.seats * monthsInInterval(before.interval),
          now,
        );
      }
    }
  }

  const committed = await commitOrThrow(before, patch, draft);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });
  if (committed.invoice) {
    await announceInvoice(committed.invoice, toIsoTimestamp(now));
  }

  return committed.subscription;
}

